using System.Collections.Concurrent;
var builder=WebApplication.CreateBuilder(args); var app=builder.Build(); app.UseDefaultFiles(); app.UseStaticFiles();
var schedules=new ConcurrentDictionary<string,DoseSchedule>(); var history=new ConcurrentQueue<DoseEvent>(); var compEvents=new ConcurrentQueue<CompEvent>();
double temp=27.4, humidity=56;
app.MapGet("/api/schedules",()=>Results.Ok(schedules.Values.OrderBy(x=>x.Time)));
app.MapPost("/api/schedules",(ScheduleInput i)=>{if(string.IsNullOrWhiteSpace(i.Person)||string.IsNullOrWhiteSpace(i.Medicine)||!TimeOnly.TryParse(i.Time,out var t)||i.Compartment<1||i.Compartment>4)return Results.BadRequest(new{message="Enter person, medicine, valid time and compartment 1-4."});var s=new DoseSchedule(Guid.NewGuid().ToString("N"),i.Person.Trim(),i.Medicine.Trim(),t.ToString("HH:mm"),i.Notes??"",i.Compartment);schedules[s.Id]=s;history.Enqueue(new(Guid.NewGuid().ToString("N"),s.Id,s.Person,s.Medicine,"Scheduled",DateTimeOffset.Now,"Schedule created",s.Compartment));return Results.Ok(s);});
app.MapDelete("/api/schedules/{id}",(string id)=>{if(!schedules.TryRemove(id,out var s))return Results.NotFound();history.Enqueue(new(Guid.NewGuid().ToString("N"),id,s.Person,s.Medicine,"Schedule removed",DateTimeOffset.Now,"Schedule deleted",s.Compartment));return Results.Ok();});
app.MapPost("/api/schedules/{id}/{action}",(string id,string action)=>{if(!schedules.TryGetValue(id,out var s))return Results.NotFound();if(action!="taken"&&action!="missed")return Results.BadRequest();var status=action=="taken"?"Taken (manual)":"Not taken (manual)";var due=DateTime.Today.Add(TimeOnly.Parse(s.Time).ToTimeSpan());var details=action=="taken"&&DateTime.Now>due?$"Manually marked taken {(int)(DateTime.Now-due).TotalMinutes} minute(s) after scheduled time":"Manually recorded by dashboard user";var ev=new DoseEvent(Guid.NewGuid().ToString("N"),id,s.Person,s.Medicine,status,DateTimeOffset.Now,details,s.Compartment);history.Enqueue(ev);return Results.Ok(ev);});
app.MapGet("/api/history",()=>Results.Ok(history.OrderByDescending(x=>x.RecordedAt).Take(500)));
app.MapGet("/api/status",()=>Results.Ok(new{temperature=temp,humidity,source="Demo values, not live sensor readings"}));
app.MapPost("/api/environment",(EnvInput i)=>{if(i.Temperature < -20||i.Temperature>80||i.Humidity<0||i.Humidity>100)return Results.BadRequest(new{message="Enter valid sample values."});temp=i.Temperature;humidity=i.Humidity;return Results.Ok(new{temperature=temp,humidity});});
app.MapPost("/api/compartment/{n}",(int n)=>{if(n<1||n>4)return Results.BadRequest();var e=new CompEvent(n,DateTimeOffset.Now,"Simulated only — servo not connected");compEvents.Enqueue(e);return Results.Ok(e);});
app.MapGet("/api/compartments",()=>Results.Ok(compEvents.OrderByDescending(x=>x.Time).Take(20)));
app.Run();
record ScheduleInput(string Person,string Medicine,string Time,string? Notes,int Compartment);
record DoseSchedule(string Id,string Person,string Medicine,string Time,string Notes,int Compartment);
record DoseEvent(string Id,string ScheduleId,string Person,string Medicine,string Status,DateTimeOffset RecordedAt,string Details,int Compartment);
record EnvInput(double Temperature,double Humidity);
record CompEvent(int Compartment,DateTimeOffset Time,string Details);